<h1 class="page-title mb-5">بررسی انتشار و گزارش‌ها</h1>
<?php foreach(['salon'=>$salons,'review'=>$reviews] as $type=>$rows): ?><section class="mb-7"><h2 class="card-title mb-3"><?= $type==='salon'?'درخواست‌های سالن':'نظرها و گزارش‌ها' ?></h2>
<?php if(!$rows): ?><p class="glass p-4">موردی برای بررسی نیست.</p><?php endif; ?>
<?php foreach($rows as $row): ?><article class="glass p-5 mb-3"><h3 class="card-title"><?= e($type==='salon'?$row['name']:$row['salon_name']) ?></h3><p><?= e($type==='salon'?($row['introduction']??''):$row['comment']) ?></p>
<?php if($type==='salon'): ?><p><?= e($row['city'].' · '.$row['address'].' · '.$row['phone']) ?></p><img class="moderation-image" src="<?= e(salon_cover_url($row)) ?>" alt="تصویر ارسالی سالن"><?php else: ?><p>امتیاز <?= e(fa_num($row['rating'])) ?> · <?= e(fa_num($row['report_count'])) ?> گزارش</p><?php foreach(App\Core\DB::select('SELECT reason FROM review_reports WHERE review_id=?',[$row['id']]) as $report): ?><p class="text-sm mt-2"><?= e($report['reason']) ?></p><?php endforeach; endif; ?>
<form method="post" action="<?= e(url('platform/moderation')) ?>" class="flex gap-3 mt-4"><?= csrf_field() ?><input type="hidden" name="type" value="<?= $type ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn-accent metal" name="decision" value="approve">تأیید انتشار</button><button class="btn-ink" name="decision" value="reject">عدم انتشار</button></form></article><?php endforeach; ?></section><?php endforeach; ?>
